package com.sena.aerolinea.aircraftmanagement.controller;

import com.sena.aerolinea.aircraftmanagement.entity.Aircraft;
import com.sena.aerolinea.aircraftmanagement.service.AircraftService;
import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.Optional;

@RestController
@RequestMapping("/api/aircrafts")
public class AircraftController {
    private final AircraftService aircraftService;

    public AircraftController(AircraftService aircraftService) {
        this.aircraftService = aircraftService;
    }

    @GetMapping
    public List<Aircraft> getAllAircrafts() {
        return aircraftService.findAll();
    }

    @GetMapping("/{id}")
    public Optional<Aircraft> getAircraftById(@PathVariable Long id) {
        return aircraftService.findById(id);
    }

    @PostMapping
    public Aircraft createAircraft(@RequestBody Aircraft aircraft) {
        return aircraftService.save(aircraft);
    }

    @PutMapping("/{id}")
    public Aircraft updateAircraft(@PathVariable Long id, @RequestBody Aircraft aircraft) {
        aircraft.setId(id);
        return aircraftService.save(aircraft);
    }

    @DeleteMapping("/{id}")
    public void deleteAircraft(@PathVariable Long id) {
        aircraftService.deleteById(id);
    }
}

